previewCss:
.darma-loader-stopwatch-sweep {
  position: relative;
  width: 46px;
  height: 52px;
}
.darma-loader-stopwatch-sweep::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 8px;
  height: 6px;
  margin-left: -4px;
  border-radius: 2px 2px 0 0;
  background: #4338ca;
}
.darma-loader-stopwatch-sweep::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 44px;
  height: 44px;
  margin-left: -22px;
  border-radius: 50%;
  border: 3px solid var(--loader-color, #6366f1);
  box-sizing: border-box;
}
.darma-loader-stopwatch-sweep i {
  position: absolute;
  left: 50%;
  bottom: 22px;
  width: 2px;
  height: 18px;
  margin-left: -1px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  transform-origin: bottom center;
  animation: darma-loader-stopwatch-sweep-spin 1.2s linear infinite;
}
.darma-loader-stopwatch-sweep i::after {
  content: "";
  position: absolute;
  bottom: -3px;
  left: 50%;
  width: 6px;
  height: 6px;
  margin-left: -3px;
  border-radius: 50%;
  background: #4338ca;
}
@keyframes darma-loader-stopwatch-sweep-spin { to { transform: rotate(360deg); } }

